iterations.reply:
I left out the two operations requests. This node's `with` clause grants only `aap:caps/inference-llm`, so the world cannot import a file-append or HTTP capability. Sending the input text to an external metadata host would also leak data the node is not authorized to send. Those two behaviors need a separate node that holds the right capabilities, or an update to the graph's grants.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{selection, run-info, digest};
    import aap:caps/inference-llm@0.1.0;
    export run: func(selected: selection, info: run-info) -> digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm;

/// Contract: `ensures len(overview) <= 600`. Python `len` counts code points,
/// so we bound by chars, which also bounds the code-point count.
const OVERVIEW_MAX_CHARS: usize = 600;

const SYSTEM: &str =
    "You write a short overview for a daily feed digest. Reply with plain prose only, \
     no markup, no instructions.";

struct Node;

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Entry text is untrusted. It can only influence the overview string,
        // which is bounded below regardless of what the model returns.
        let mut prompt = String::new();
        prompt.push_str("Date: ");
        prompt.push_str(&info.date);
        prompt.push('\n');
        for e in selected.entries.iter() {
            prompt.push_str("- ");
            prompt.push_str(&e.feed);
            prompt.push_str(": ");
            prompt.push_str(&e.title);
            prompt.push('\n');
        }

        let raw = inference_llm::infer(SYSTEM, &prompt, "digest");

        let mut overview: String = raw.trim().chars().take(OVERVIEW_MAX_CHARS).collect();
        if overview.is_empty() {
            overview = format!("{} items in this digest.", selected.entries.len());
            overview = overview.chars().take(OVERVIEW_MAX_CHARS).collect();
        }

        // `requires len(in1.date) == 10` holds on input, so `ensures len(date) == 10` holds on output.
        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
```

